def splitArray(nums, k):
    # Helper to determine if we can split nums into ≤k subarrays with sums ≤max_sum
    def can_split(max_sum):
        count = 1
        total = 0
        for num in nums:
            total += num
            if total > max_sum:
                # Need an extra subarray
                count += 1
                total = num
                if count > k:
                    return False
        return True

    left, right = max(nums), sum(nums)
    while left < right:
        mid = (left + right) // 2
        if can_split(mid):
            right = mid
        else:
            left = mid + 1
    return left
